corporate_design.toad_component_blueprint:
canvas {
  size: 880px 580px;
  fill: #FBF7F0;
  font-family: "Space Grotesk, sans-serif";
}

>roast = #3B1F17;
>cherry = #C2410C;

rect #roastCard {
  at: center of canvas;
  size: 780px 480px;
  fill: #FFFFFF;
  stroke: >roast;
  stroke-width: 1px;
  radius: 12px;
}

text #roastTag {
  at: top left of #roastCard offset 40px 40px;
  content: "RÖSTWERK // SINGLE ORIGIN ETHIOPIA YIRGACHEFFE";
  font-size: 13px;
  font-weight: 700;
  color: >cherry;
}

text #cuppingScore {
  at: below #roastTag offset 16px;
  content: "SCA Score 88.5 • Florale Noten & Bergamotte";
  font-size: 28px;
  font-weight: 700;
  color: >roast;
}
